<?php declare(strict_types=1); namespace App\Web\Admin\Permission\Edit; use App\Permission\PermissionRepository; use Psr\Http\Message\{ResponseFactoryInterface,ResponseInterface,ServerRequestInterface}; use Yiisoft\Router\HydratorAttribute\RouteArgument; use Yiisoft\Router\UrlGeneratorInterface; use Yiisoft\Yii\View\Renderer\WebViewRenderer; final readonly class Action{public function __construct(private PermissionRepository $permissions,private WebViewRenderer $view,private ResponseFactoryInterface $factory,private UrlGeneratorInterface $url){} public function __invoke(ServerRequestInterface $r,#[RouteArgument]int $id):ResponseInterface{$p=$this->permissions->findById($id);if(!$p)return $this->factory->createResponse(404);if($r->getMethod()==='POST'){$this->permissions->update($p,(string)($r->getParsedBody()['title']??''));return $this->factory->createResponse(302)->withHeader('Location',$this->url->generate('admin/permission/index'));}return $this->view->render(__DIR__.'/template',['permission'=>$p]);}}
